"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["879"],{6402(e,t,o){o.r(t),o.d(t,{metadata:()=>n,default:()=>h,frontMatter:()=>s,contentTitle:()=>r,toc:()=>d,assets:()=>c});var n=JSON.parse('{"id":"how-to/hardware/test","title":"Test your solution","description":"av \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/how-to/hardware/test.md","sourceDirName":"how-to/hardware","slug":"/how-to/hardware/test","permalink":"/personal-av-docs/docs/how-to/hardware/test","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/how-to/hardware/test.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"Test your solution","sidebar_label":"Test your solution","sidebar_position":99,"edition":"av","source":"https://doc.airvantage.net/av/howto/hardware/test","format":"md"}}'),a=o(4848),i=o(8453);let s={title:"Test your solution",sidebar_label:"Test your solution",sidebar_position:99,edition:"av",source:"https://doc.airvantage.net/av/howto/hardware/test",format:"md"},r,c={},d=[];function u(e){let t={a:"a",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsxs)(t.p,{children:[":::note Edition\n",(0,a.jsx)(t.strong,{children:"av"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,a.jsx)(t.a,{href:"https://doc.airvantage.net/av/howto/hardware/test",children:"Original page"}),".\n:::"]}),"\n",(0,a.jsx)(t.p,{children:"Test your solution\nThe next step when you develop an application is to test its behavior. AirVantage provides several features to help you debug and validate your IoT solution.\nWe assume you have already registered your system and you configured it to use your application. Now you want to troubleshoot the overall solution. The first step is to be sure your system is communicating well with AirVantage.\n1 /\nConnection\n2 /\nValues\n3 /\nInteract\nStep 1: Test the connection\nAirVantage provides several types of information regarding the state of the connection.\nCheck the connection\nAirVantage stores the Last Communication Date of each system.\nIf you registered the device in the READY state, it will switch automatically in the DEPLOYED state at the first communication.\nIf you implement a regular connection to AirVantage, for instance your device is sending data every 1h, you can configure the communication pattern on the device and define some rules to detect communication failure. Depending on this configuration, the Communication Status will switch from OK, WARNING, ERROR accordingly. See the dedicated article about\nHeartbeat, Communication status and Alerts\n.\nDebug Communication\nTo be sure your system is communicating well, AirVantage proposes a screen to see all the messages received from a given system.\nIt\u2019s available through Monitor > Systems. Select your system and go to its details page then click the \u201CTimeline\u201D button.\nYou should see the screen on the right.\nEach bar represents a communication received by AirVantage for the selected system. If you click one of the bars, the data sent in this communication is displayed under the graph.\nSo if you don\u2019t see a communication bar where you expected one, check the communication configuration on the embedded side:\nThe identifier\nThe URL of the server\nThe password\nThe network configuration\nIn each bar, the set of data sent to the server is listed. So you can check all data has been sent correctly. If data is displayed with a path, that means your application model is not correct and you may check the path consistency between the embedded application and the application model.\nStep 2: Check your values\nYou can display your data in a chart to see recent history. Read this\nhowto\nto add a new widget in your dashboard.\nThis\ntutorial\nshows you how to export your data manually.\nStep 3: Interact with your system\nOnce the communication between AirVantage and the device is working fine, you want to validate the behavior of your solution more comprehensively.\nYou can interact with the device using \u201CApply settings\u201D and \u201CSend commands\u201D operations (depending on the features supported by your embedded applications).\nSend commands\nTo send commands, you go to Monitor > Systems, select your system and go to its details page. Then you can click on the \u201CMore\u201D button and select the \u201CCustom command\u201D action.\nIt opens the following dialog. In this dialog, you can select one of the commands available on your system. When you click on \u201CCreate\u201D, it initializes a \u201CCustom command\u201D operation (in progress state)\nYou can check the progress of this operation by switching to the \u201COperations\u201D tab. The operation will be executed by default at the next communication from the system.\nThe\nSend Command\noperation status on AirVantage portal should be changed to green, indicating a successful completion\nApply settings\nTo send a value, you need to have declared a setting in the application model associated to your system. Then you can edit it by following these steps:\nFind your system in the\nMonitor\nactivity > Systems, select your system and go to its details page.\nGo to the\ndetail page\nof the application containing the setting you want to modify. Here you can see the values sent by the device.\nTo modify a value, click the\nEdit\nbutton. You can change the value of the settings of your application (the settings are defined in the model of your application).\nModify the values and click\nApply\nat the bottom of the page. An operation \u201CApply settings operation\u201D is created to perform the task.\nGo back to the system details page to monitor all system operations. The operation will be executed by default at the next communication from the system.\nRequest the device to send back a value\nThe mechanism by which you can request values from a device using Airvantage works through\nDataset\n. A Dataset specifies a list of\nvariables\nand\nsettings\nthat AirVantage has to retrieve from the device.\nYou need to\ncreate a dataset\n.\nFrom the\nMonitor\nactivity, on your system detail, you will be able to launch a\nretrieve device data\noperation."})]})}function h(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(u,{...e})}):u(e)}},8453(e,t,o){o.d(t,{R:()=>s,x:()=>r});var n=o(6540);let a={},i=n.createContext(a);function s(e){let t=n.useContext(i);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),n.createElement(i.Provider,{value:t},e.children)}}}]);